// SPDX-License-Identifier: Solderpad-0.51
//
// E2 probe timing block for the 2026-10-03 two-BIT implementation contract.
//
// This module is passive: none of its outputs drive DMA, IOTLB, translation,
// command queues, or interrupts.  It only records the V/DID10 interval after a
// legally accepted PROBE command.  The observer instantiates it read-only.
//
// Register meaning in the observer local index window (D80..D8F):
//   D80 magic 0x49444d4145325431 (IDMAE2T1)
//   D81 version 1
//   D82 error
//   D83 flags[2:0] = issue_seen, select_seen, done_seen
//   D84 V issue epoch after PROBE
//   D85 first V select epoch
//   D86 V done epoch
//   D87 done - issue cycles
//   D88 first_select - issue cycles
//   D89 V REQ_TRANS/AWAIT_RESP occupancy cycles
//   D8A V COMPLETE cycles
//   D8B V select count
//   D8C V hit count
//   D8D V miss count
//   D8E..D8F reserved (read zero)
//
// Error bits:
//   [0] counter overflow
//   [1] duplicate V issue
//   [2] V done without issue
//   [3] duplicate V done
//   [4] response_error during active interval
//   [5] unsupported during armed/active interval
//
// Clearing is accepted only from the already-legal observer CLEAR path.
module dma_research_e2_timing #(
    parameter int unsigned CounterWidth = 64
) (
    input  logic          clk_i,
    input  logic          rst_ni,

    input  logic          clear_i,
    input  logic          probe_accept_i,
    input  logic [2:0]    phase_i,
    input  logic [63:0]   epoch_i,

    input  logic          issue_v_i,
    input  logic          done_v_i,
    input  logic          select_v_i,
    input  logic          ctl_v_i,
    input  logic [2:0]    ctl_state_i,
    input  logic          lookup_v_i,
    input  logic          lookup_hit_i,
    input  logic          response_error_i,
    input  logic          unsupported_i,

    output logic [15:0]   error_o,
    output logic [63:0]   flags_o,
    output logic [63:0]   issue_epoch_o,
    output logic [63:0]   first_select_epoch_o,
    output logic [63:0]   done_epoch_o,
    output logic [63:0]   done_issue_cycles_o,
    output logic [63:0]   first_select_issue_cycles_o,
    output logic [63:0]   v_main_cycles_o,
    output logic [63:0]   v_comp_cycles_o,
    output logic [63:0]   v_select_count_o,
    output logic [63:0]   v_hit_count_o,
    output logic [63:0]   v_miss_count_o
);

    localparam logic [2:0] ST_REQ_TRANS  = 3'd1;
    localparam logic [2:0] ST_AWAIT_RESP = 3'd2;
    localparam logic [2:0] ST_COMPLETE   = 3'd4;

    localparam logic [2:0] T_IDLE   = 3'd0;
    localparam logic [2:0] T_ARMED  = 3'd1;
    localparam logic [2:0] T_ACTIVE = 3'd2;
    localparam logic [2:0] T_DONE   = 3'd3;

    logic [2:0]  state_q, state_n;
    logic [15:0] err_q, err_n;
    logic [63:0] flags_q, flags_n;

    logic [63:0] issue_epoch_q, issue_epoch_n;
    logic [63:0] first_select_epoch_q, first_select_epoch_n;
    logic [63:0] done_epoch_q, done_epoch_n;
    logic [63:0] done_issue_q, done_issue_n;
    logic [63:0] first_select_issue_q, first_select_issue_n;

    logic [CounterWidth-1:0] v_main_q, v_main_n;
    logic [CounterWidth-1:0] v_comp_q, v_comp_n;
    logic [CounterWidth-1:0] v_sel_q,  v_sel_n;
    logic [CounterWidth-1:0] v_hit_q,  v_hit_n;
    logic [CounterWidth-1:0] v_miss_q, v_miss_n;

    logic interval_active;
    logic [63:0] issue_epoch_now;

    assign interval_active = (state_q == T_ACTIVE) ||
                             ((state_q == T_ARMED) && issue_v_i);

    assign issue_epoch_now = ((state_q == T_ARMED) && issue_v_i) ? epoch_i : issue_epoch_q;

    // phase_i is part of the integration contract.  The timing state itself is
    // driven by the legal PROBE/CLEAR pulses and the V event taps.
    /* verilator lint_off UNUSED */
    logic unused_phase;
    assign unused_phase = ^phase_i;
    /* verilator lint_on UNUSED */

    always_comb begin
        state_n = state_q;
        err_n   = err_q;
        flags_n = flags_q;

        issue_epoch_n = issue_epoch_q;
        first_select_epoch_n = first_select_epoch_q;
        done_epoch_n = done_epoch_q;
        done_issue_n = done_issue_q;
        first_select_issue_n = first_select_issue_q;

        v_main_n = v_main_q;
        v_comp_n = v_comp_q;
        v_sel_n  = v_sel_q;
        v_hit_n  = v_hit_q;
        v_miss_n = v_miss_q;

        if (clear_i) begin
            state_n = T_IDLE;
            err_n   = 16'd0;
            flags_n = 64'd0;
            issue_epoch_n = 64'd0;
            first_select_epoch_n = 64'd0;
            done_epoch_n = 64'd0;
            done_issue_n = 64'd0;
            first_select_issue_n = 64'd0;
            v_main_n = '0;
            v_comp_n = '0;
            v_sel_n  = '0;
            v_hit_n  = '0;
            v_miss_n = '0;
        end else begin
            if (probe_accept_i && (state_q == T_IDLE)) state_n = T_ARMED;

            if (unsupported_i && ((state_q == T_ARMED) || (state_q == T_ACTIVE)))
                err_n[5] = 1'b1;
            if (response_error_i && interval_active)
                err_n[4] = 1'b1;

            if (issue_v_i) begin
                if (state_q == T_ARMED) begin
                    state_n = T_ACTIVE;
                    issue_epoch_n = epoch_i;
                    flags_n[0] = 1'b1;
                end else if ((state_q == T_ACTIVE) || (state_q == T_DONE)) begin
                    err_n[1] = 1'b1;
                end
            end

            if (done_v_i) begin
                if ((state_q == T_ACTIVE) || ((state_q == T_ARMED) && issue_v_i)) begin
                    state_n = T_DONE;
                    done_epoch_n = epoch_i;
                    flags_n[2] = 1'b1;
                    done_issue_n = epoch_i - issue_epoch_now;
                end else if (state_q == T_DONE) begin
                    err_n[3] = 1'b1;
                end else if (state_q == T_ARMED) begin
                    err_n[2] = 1'b1;
                    state_n = T_DONE;
                    done_epoch_n = epoch_i;
                    flags_n[2] = 1'b1;
                end
            end

            if (interval_active) begin
                if (ctl_v_i && ((ctl_state_i == ST_REQ_TRANS) || (ctl_state_i == ST_AWAIT_RESP))) begin
                    if (&v_main_q) err_n[0] = 1'b1;
                    v_main_n = v_main_q + 1'b1;
                end
                if (ctl_v_i && (ctl_state_i == ST_COMPLETE)) begin
                    if (&v_comp_q) err_n[0] = 1'b1;
                    v_comp_n = v_comp_q + 1'b1;
                end
                if (select_v_i) begin
                    if (&v_sel_q) err_n[0] = 1'b1;
                    v_sel_n = v_sel_q + 1'b1;
                    if (!flags_q[1]) begin
                        first_select_epoch_n = epoch_i;
                        first_select_issue_n = epoch_i - issue_epoch_now;
                        flags_n[1] = 1'b1;
                    end
                end
                if (lookup_v_i) begin
                    if (lookup_hit_i) begin
                        if (&v_hit_q) err_n[0] = 1'b1;
                        v_hit_n = v_hit_q + 1'b1;
                    end else begin
                        if (&v_miss_q) err_n[0] = 1'b1;
                        v_miss_n = v_miss_q + 1'b1;
                    end
                end
            end
        end
    end

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            state_q <= T_IDLE;
            err_q   <= 16'd0;
            flags_q <= 64'd0;
            issue_epoch_q <= 64'd0;
            first_select_epoch_q <= 64'd0;
            done_epoch_q <= 64'd0;
            done_issue_q <= 64'd0;
            first_select_issue_q <= 64'd0;
            v_main_q <= '0;
            v_comp_q <= '0;
            v_sel_q  <= '0;
            v_hit_q  <= '0;
            v_miss_q <= '0;
        end else begin
            state_q <= state_n;
            err_q   <= err_n;
            flags_q <= flags_n;
            issue_epoch_q <= issue_epoch_n;
            first_select_epoch_q <= first_select_epoch_n;
            done_epoch_q <= done_epoch_n;
            done_issue_q <= done_issue_n;
            first_select_issue_q <= first_select_issue_n;
            v_main_q <= v_main_n;
            v_comp_q <= v_comp_n;
            v_sel_q  <= v_sel_n;
            v_hit_q  <= v_hit_n;
            v_miss_q <= v_miss_n;
        end
    end

    assign error_o = err_q;
    assign flags_o = flags_q;
    assign issue_epoch_o = issue_epoch_q;
    assign first_select_epoch_o = first_select_epoch_q;
    assign done_epoch_o = done_epoch_q;
    assign done_issue_cycles_o = done_issue_q;
    assign first_select_issue_cycles_o = first_select_issue_q;
    assign v_main_cycles_o = 64'(v_main_q);
    assign v_comp_cycles_o = 64'(v_comp_q);
    assign v_select_count_o = 64'(v_sel_q);
    assign v_hit_count_o = 64'(v_hit_q);
    assign v_miss_count_o = 64'(v_miss_q);

endmodule

// Directed Verilator test for dma_research_e2_timing.sv.
// Simulation only; no board claim and no execution claim.
#include "Vdma_research_e2_timing.h"
#include "verilated.h"
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <stdexcept>
#include <string>

static int checks = 0;
static void check(bool c, const char *m) {
    if (!c) throw std::runtime_error(m);
    checks++;
}

struct TB {
    Vdma_research_e2_timing d;

    void tick(unsigned n = 1) {
        while (n--) {
            d.clk_i = 0; d.eval();
            d.clk_i = 1; d.eval();
            d.clk_i = 0; d.eval();
        }
    }

    void reset() {
        d.clear_i = 0; d.probe_accept_i = 0; d.phase_i = 0; d.epoch_i = 0;
        d.issue_v_i = 0; d.done_v_i = 0; d.select_v_i = 0;
        d.ctl_v_i = 0; d.ctl_state_i = 0;
        d.lookup_v_i = 0; d.lookup_hit_i = 0;
        d.response_error_i = 0; d.unsupported_i = 0;
        d.rst_ni = 0; tick(2); d.rst_ni = 1; tick(1);
    }

    void clear() { d.clear_i = 1; tick(1); d.clear_i = 0; d.eval(); }
    void probe() { d.probe_accept_i = 1; tick(1); d.probe_accept_i = 0; d.eval(); }
};

static void t_basic_edges() {
    TB t; t.reset(); t.clear(); t.probe();

    // Issue edge at epoch 100, V owns REQ_TRANS.
    t.d.epoch_i = 100; t.d.issue_v_i = 1; t.d.ctl_v_i = 1; t.d.ctl_state_i = 1;
    t.tick(1);
    t.d.issue_v_i = 0; t.d.eval();

    // Occupancy cycles 101, 102; select at 102.
    t.d.epoch_i = 101; t.tick(1);
    t.d.epoch_i = 102; t.d.select_v_i = 1; t.tick(1);
    t.d.select_v_i = 0; t.d.eval();

    // Hit then miss in the active interval.
    t.d.lookup_v_i = 1; t.d.lookup_hit_i = 1; t.d.epoch_i = 103; t.tick(1);
    t.d.lookup_hit_i = 0; t.d.epoch_i = 104; t.tick(1);
    t.d.lookup_v_i = 0; t.d.eval();

    // Completion edge at 110, V owns COMPLETE.
    t.d.epoch_i = 110; t.d.done_v_i = 1; t.d.ctl_state_i = 4; t.tick(1);
    t.d.done_v_i = 0; t.d.eval();

    check(t.d.flags_o == ((1ULL << 0) | (1ULL << 1) | (1ULL << 2)), "flags issue/select/done");
    check(t.d.issue_epoch_o == 100, "issue epoch");
    check(t.d.first_select_epoch_o == 102, "first select epoch");
    check(t.d.done_epoch_o == 110, "done epoch");
    check(t.d.done_issue_cycles_o == 10, "done-issue cycles");
    check(t.d.first_select_issue_cycles_o == 2, "first select-issue cycles");
    check(t.d.v_main_cycles_o == 5, "V main occupancy");
    check(t.d.v_comp_cycles_o == 1, "V complete cycles");
    check(t.d.v_select_count_o == 1, "V select count");
    check(t.d.v_hit_count_o == 1, "V hit count");
    check(t.d.v_miss_count_o == 1, "V miss count");
}

static void t_repeats_and_clear() {
    TB t; t.reset(); t.clear(); t.probe();
    t.d.epoch_i = 10; t.d.issue_v_i = 1; t.d.ctl_v_i = 1; t.d.ctl_state_i = 1; t.tick(1);
    t.d.issue_v_i = 0; t.d.epoch_i = 20; t.d.done_v_i = 1; t.d.ctl_state_i = 4; t.tick(1);
    t.d.done_v_i = 0; t.d.eval();

    // Duplicate issue and duplicate done are sticky errors.
    t.d.epoch_i = 21; t.d.issue_v_i = 1; t.tick(1); t.d.issue_v_i = 0; t.d.eval();
    check((t.d.error_o & (1u << 1)) != 0, "duplicate issue error");
    t.d.epoch_i = 22; t.d.done_v_i = 1; t.tick(1); t.d.done_v_i = 0; t.d.eval();
    check((t.d.error_o & (1u << 3)) != 0, "duplicate done error");

    t.clear();
    check(t.d.error_o == 0, "clear error");
    check(t.d.flags_o == 0, "clear flags");
    check(t.d.done_issue_cycles_o == 0, "clear done cycles");
    check(t.d.v_main_cycles_o == 0, "clear V main");
}

static void t_done_without_issue_and_faults() {
    TB t; t.reset(); t.clear(); t.probe();
    t.d.epoch_i = 30; t.d.done_v_i = 1; t.tick(1); t.d.done_v_i = 0; t.d.eval();
    check((t.d.error_o & (1u << 2)) != 0, "done without issue error");

    t.reset(); t.clear(); t.probe();
    t.d.epoch_i = 40; t.d.issue_v_i = 1; t.d.ctl_v_i = 1; t.d.ctl_state_i = 1; t.tick(1);
    t.d.issue_v_i = 0; t.d.eval();
    t.d.response_error_i = 1; t.tick(1); t.d.response_error_i = 0; t.d.eval();
    check((t.d.error_o & (1u << 4)) != 0, "response error during active interval");
    t.d.unsupported_i = 1; t.tick(1); t.d.unsupported_i = 0; t.d.eval();
    check((t.d.error_o & (1u << 5)) != 0, "unsupported during active interval");
}

static void t_overflow_small() {
    TB t; t.reset(); t.clear(); t.probe();
    t.d.epoch_i = 1; t.d.issue_v_i = 1; t.d.ctl_v_i = 1; t.d.ctl_state_i = 1; t.tick(1);
    t.d.issue_v_i = 0; t.d.eval();
    for (int i = 0; i < 300; i++) { t.d.epoch_i++; t.tick(1); }
    check((t.d.error_o & 1u) != 0, "counter overflow sticky small variant");
    check(t.d.v_main_cycles_o == (301ULL & 0xFFULL), "8-bit V main counter wrapped");
}

int main(int argc, char **argv) {
    Verilated::commandArgs(argc, argv);
    bool small = (argc > 1 && std::string(argv[1]) == "small");
    try {
        if (small) {
            t_overflow_small();
        } else {
            t_basic_edges();
            t_repeats_and_clear();
            t_done_without_issue_and_faults();
        }
        std::cout << "PASS " << checks << " E2 timing checks (simulation only)" << std::endl;
        return 0;
    } catch (const std::exception &e) {
        std::cerr << "FAIL after " << checks << " checks: " << e.what() << std::endl;
        return 1;
    }
}

`include "common_cells/registers.svh"
`include "idma/typedef.svh"
module idma_research_frontend_top (
    input  logic clk_i, rst_ni,
    input  logic valid_i, write_i,
    input  logic [7:0] addr_i,
    input  logic [63:0] wdata_i,
    input  logic [7:0] wstrb_i,
    input  logic ready_i, complete_i, backend_idle_i,
    input  logic policy_enable_i, policy_allow_i, policy_abort_i, batch_reverse_i,
    output logic [63:0] rdata_o,
    output logic ready_o, error_o,
    output logic request_o,
    output logic [63:0] length_o, src_o, dst_o,
    output logic [1:0] type_o,
    output logic batch_active_o,
    output logic issue_o, done_o,
    output logic [63:0] issue_id_o, done_id_o
);
    typedef struct packed {logic valid, write; logic [7:0] addr; logic [63:0] wdata; logic [7:0] wstrb;} req_t;
    typedef struct packed {logic ready, error; logic [63:0] rdata;} rsp_t;
    typedef logic [63:0] addr_t;
    typedef logic [3:0] id_t;
    `IDMA_TYPEDEF_FULL_REQ_T(burst_t, id_t, addr_t, addr_t)

    req_t req;
    rsp_t rsp;
    burst_t burst;
    logic request;
    logic [1:0] ttype;
    logic [63:0] wdata;

    assign req = {valid_i, write_i, addr_i, wdata_i, wstrb_i};

    idma_reg64_frontend #(
        .dma_regs_req_t(req_t), .dma_regs_rsp_t(rsp_t),
        .burst_req_t(burst_t), .AxiIdWidth(4),
        .ObserverPort(1'b1), .BatchPort(1'b1), .LaunchPort(1'b0),
        .ResearchPort(1'b1)
    ) dut (
        .clk_i, .rst_ni, .dma_ctrl_req_i(req), .dma_ctrl_rsp_o(rsp),
        .burst_req_o(burst), .valid_o(request), .ready_i(ready_i),
        .backend_idle_i(backend_idle_i), .trans_complete_i(complete_i),
        .ttype_o(ttype), .wdata_o(wdata), .rdata_i('0), .rdata_valid_i(1'b0),
        .batch_active_o(batch_active_o),
        .policy_enable_i(policy_enable_i), .policy_allow_i(policy_allow_i),
        .policy_abort_i(policy_abort_i), .batch_reverse_i(batch_reverse_i),
        .obs_issue_o(issue_o), .obs_done_o(done_o), .obs_poll_o(),
        .obs_issue_id_o(issue_id_o), .obs_done_id_o(done_id_o), .obs_poll_id_o(),
        .obs_cfg_valid_o(), .obs_cfg_write_o(), .obs_cfg_addr_o(),
        .obs_cfg_wdata_o(), .obs_cfg_wstrb_o(), .obs_cfg_rdata_i('0),
        .launch_hold_i(1'b0), .launch_go_i(1'b0), .launch_cancel_i(1'b0),
        .launch_held_o(), .launch_active_o(), .launch_cancelled_o(), .launch_error_o()
    );

    assign rdata_o = rsp.rdata;
    assign ready_o = rsp.ready;
    assign error_o = rsp.error;
    assign request_o = request;
    assign length_o = burst.length;
    assign src_o = burst.src_addr;
    assign dst_o = burst.dst_addr;
    assign type_o = ttype;
endmodule

// Directed Verilator test for ResearchPort batch admission and reverse order.
// Simulation only; no board claim and no execution claim.
#include "Vidma_research_frontend_top.h"
#include "verilated.h"
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <vector>

static void ck(bool b, const char *s) {
    if (!b) throw std::runtime_error(s);
}

struct FE {
    Vidma_research_frontend_top d;
    uint64_t cycle = 0;
    bool valid = false, write = false;
    uint8_t addr = 0;
    uint64_t wdata = 0, wstrb = 0xff;
    bool ready = true;
    bool due_valid = false;
    uint64_t due = 0;
    bool policy_enable = false, policy_allow = false, policy_abort = false, batch_reverse = false;
    unsigned completions = 0;
    uint64_t last_done_id = 0;
    bool have_done = false;
    std::vector<uint64_t> srcs;

    void eval() {
        d.valid_i = valid;
        d.write_i = write;
        d.addr_i = addr;
        d.wdata_i = wdata;
        d.wstrb_i = wstrb;
        d.ready_i = ready;
        d.complete_i = due_valid && (cycle == due);
        d.backend_idle_i = !due_valid;
        d.policy_enable_i = policy_enable;
        d.policy_allow_i = policy_allow;
        d.policy_abort_i = policy_abort;
        d.batch_reverse_i = batch_reverse;
        d.eval();
    }

    void tick() {
        eval();
        if (d.rst_ni) {
            if (d.request_o && d.ready_i) {
                ck(!due_valid, "one outstanding task");
                srcs.push_back(d.src_o);
                due_valid = true;
                due = cycle + 3;
            }
        }
        if (d.rst_ni && d.complete_i) {
            ck(d.done_o, "batch done on completion");
            completions++;
            last_done_id = d.done_id_o;
            have_done = true;
            due_valid = false;
        }
        d.clk_i = 1; d.eval();
        cycle++;
        d.clk_i = 0; d.eval();
    }

    void reset() {
        d.rst_ni = 0;
        valid = false; write = false; addr = 0; wdata = 0; wstrb = 0xff;
        ready = true; due_valid = false; due = 0;
        policy_enable = false; policy_allow = false; policy_abort = false; batch_reverse = false;
        completions = 0; last_done_id = 0; have_done = false; srcs.clear();
        for (int i = 0; i < 3; i++) { eval(); d.clk_i = 1; d.eval(); d.clk_i = 0; d.eval(); }
        d.rst_ni = 1; eval(); d.clk_i = 1; d.eval(); d.clk_i = 0; d.eval();
    }

    FE() { reset(); }

    uint64_t access(unsigned a, bool wr = false, uint64_t val = 0, uint8_t strb = 0xff) {
        valid = true; write = wr; addr = (uint8_t)a; wdata = val; wstrb = strb;
        eval();
        ck(d.ready_o, "frontend MMIO ready");
        uint64_t r = d.rdata_o;
        tick();
        valid = false; wstrb = 0xff; eval();
        return r;
    }

    void configure(uint32_t target, unsigned p, bool reverse = false) {
        batch_reverse = reverse;
        access(0x00, true, 0x10000);
        access(0x08, true, 0x100000);
        access(0x10, true, 4096);
        access(0x18, true, 0);
        access(0x88, true, 0);
        access(0x90, true, target);
        access(0x98, true, p);
        access(0x88, true, 1);
    }

    void start() {
        uint64_t id = access(0x28);
        ck(id == 2, "one functional ID per batch");
    }

    void run_until(unsigned n, unsigned limit = 200000) {
        for (unsigned i = 0; i < limit && completions < n; i++) tick();
        ck(completions == n, "bounded completion count");
    }
};

int main(int argc, char **argv) {
    Verilated::commandArgs(argc, argv);
    try {
        unsigned cases = 0;

        // First copy: policy enable enters ADMIT and asserts no VALID until allow.
        {
            FE b; b.policy_enable = true; b.configure(4, 1, false); b.start();
            for (int i = 0; i < 5; i++) { b.tick(); ck(!b.d.request_o, "no VALID in ADMIT before allow"); }
            b.policy_allow = true;
            b.tick();
            ck(b.d.request_o, "VALID after allow");
            cases++;
        }

        // Per-copy ADMIT: after a completed copy, wait for allow again.
        {
            FE b; b.policy_enable = true; b.policy_allow = true; b.configure(2, 1, false); b.start();
            for (int i = 0; i < 100 && b.srcs.size() < 1; i++) b.tick();
            ck(b.srcs.size() == 1, "first copy offered");
            b.policy_allow = false;
            b.run_until(1);
            for (int i = 0; i < 4; i++) { b.tick(); ck(!b.d.request_o, "no second copy before allow"); }
            b.policy_allow = true;
            b.run_until(2);
            ck(b.srcs.size() == 2, "second copy offered after allow");
            cases++;
        }

        // COUNTVALID is held through a policy abort until backend ready.
        {
            FE b; b.policy_enable = true; b.policy_allow = true; b.configure(4, 1, false); b.start();
            for (int i = 0; i < 100 && !b.d.request_o; i++) b.tick();
            ck(b.d.request_o, "request pending in COUNT");
            uint64_t src0 = b.d.src_o;
            b.ready = false;
            b.policy_abort = true;
            for (int i = 0; i < 8; i++) {
                b.eval();
                ck(b.d.request_o, "abort cannot withdraw stalled VALID");
                ck(b.d.src_o == src0, "stalled payload stable");
                b.tick();
            }
            b.ready = true;
            b.tick();
            b.run_until(1);
            ck(b.completions == 1, "committed aborted copy completed once");
            b.policy_abort = false;
            for (int i = 0; i < 5; i++) { b.tick(); ck(!b.d.request_o, "abort retires after WAIT completion"); }
            cases++;
        }

        // STOP in ADMIT retires immediately and creates no obs_done.
        {
            FE b; b.policy_enable = true; b.policy_allow = false; b.configure(4, 1, false); b.start();
            b.tick();
            ck(!b.d.request_o, "ADMIT does not send VALID");
            b.access(0x88, true, 2);
            b.tick(); b.tick();
            ck(!b.d.batch_active_o, "STOP in ADMIT retires");
            ck(!b.have_done, "STOP in ADMIT no obs_done");
            cases++;
        }

        // Policy abort in ADMIT retires immediately and creates no obs_done.
        {
            FE b; b.policy_enable = true; b.policy_allow = false; b.configure(4, 1, false); b.start();
            b.policy_abort = true;
            b.tick(); b.tick();
            ck(!b.d.batch_active_o, "policy abort in ADMIT retires");
            ck(!b.have_done, "policy abort in ADMIT no obs_done");
            cases++;
        }

        // Reverse order is latched at batch issue, starts at pages-1, subtracts
        // 4 KiB and wraps.  target=8 and pages=4 exercises a full wrap.
        {
            FE b; b.policy_enable = true; b.policy_allow = true; b.configure(8, 4, true); b.start();
            b.run_until(8);
            ck(b.srcs.size() == 8, "eight reverse copies");
            const uint64_t base = 0x10000;
            for (int i = 0; i < 8; i++) {
                uint64_t expect = base + ((uint64_t)(3 - (i % 4)) << 12);
                ck(b.srcs[i] == expect, "reverse page order with wrap");
            }
            cases++;
        }

        std::cout << "PASS " << cases << " ResearchPort frontend scenarios\n";
        return 0;
    } catch (const std::exception &e) {
        std::cerr << "FAIL " << e.what() << "\n";
        return 1;
    }
}

